fn pack(language: Language) -> Option<&'static [(&'static str, &'static str)]> {
    match language {
        Language::Ja => Some(JA),
        Language::Ko => Some(KO),
        Language::De => Some(DE),
        Language::Fr => Some(FR),
        Language::Es => Some(ES),
        Language::Ru => Some(RU),
        Language::Pt => Some(PT),
        Language::It => Some(IT),
        Language::Nl => Some(NL),
        Language::Pl => Some(PL),
        Language::Tr => Some(TR),
        Language::Ar => Some(AR),
        Language::Hi => Some(HI),
        Language::Th => Some(TH),
        Language::Vi => Some(VI),
        Language::Id => Some(ID),
        Language::Uk => Some(UK),
        Language::Cs => Some(CS),
        _ => None,
    }
}
